import {CATEGORIES,LABELS,outputPower,sliceWaveform} from './engine.js?v=2.0.0';
import {collectAnalysisNotes} from './analysis-notes.js?v=2.0.0';
import {characteristicTitle} from './preflight.js?v=2.0.0';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=v=>Number.isFinite(v)?Number(v.toPrecision(5)).toString():'—';
const palette=['#c6f278','#82bfff','#c6a0f6','#f6b56d','#79d8c1','#f49cac','#a6b6c8'];
export function resultState(row,project){if(!row)return 'Not calculated';if(!row.valid)return row.devices?.some(d=>d.valid)?'Incomplete':'Failed';const notes=collectAnalysisNotes([row],project);return notes.warnings.length||notes.assumptions.length?'Complete with assumptions':'Complete';}
export function projectSummary(project){return `<div class="study-summary"><h2>Project summary before calculation</h2><p>${project.waveforms.length} operating-point files · ${project.instances.length} component banks · ${project.instances.length?project.instances.reduce((v,i)=>v*i.candidates.length,1):0} alternative combinations</p><p>Window: ${n(project.operating.window)} s · ${e(project.operating.interpolationMethod||'reference-first')} · domain: ${e(project.operating.domainPolicy||'error')}</p>${project.instances.map(inst=>`<section><h3>${e(inst.name)} · ${e(inst.type)}</h3>${inst.candidates.map(c=>`<p><b>${e(c.part||'Unnamed alternative')}</b>: series ${n(c.series)}, parallel ${n(c.parallel)}, total ${n(c.totalCount)}. Enabled: ${e(c.enabled.map(k=>LABELS[k]).join(', ')||'None')}. Temperature: ${e(c.thermal.mode)} ${n(c.thermal.temperature)} °C${c.thermal.mode==='iterative'?', Rth '+n(c.thermal.Rth)+' K/W ('+e(c.thermal.scope)+')':''}.</p>${c.curves.filter(cr=>cr.originPolicy==='zero'||cr.negativeOutputPolicy==='zero'||cr.temperatureIndependent||cr.voltageScaling===false||Object.values(cr.dependencyPolicy||{}).some(v=>v.enabled===false)).map(cr=>`<p class="caption">${e(characteristicTitle(cr))}: ${[cr.originPolicy==='zero'?'zero-current origin':'',cr.negativeOutputPolicy==='zero'?'negative-output zero floor':'',cr.temperatureIndependent?'temperature-independent':'',cr.voltageScaling===false?'voltage scaling disabled':'',...Object.entries(cr.dependencyPolicy||{}).filter(([,v])=>v.enabled===false).map(([k,v])=>k+' fixed at '+v.reference)].filter(Boolean).map(e).join(' · ')}</p>`).join('')}`).join('')}</section>`).join('')}<p class="caption">Reverse gate-on MOSFET current uses the symmetric channel model. Disabled losses, auxiliary/control losses, interconnects and dedicated transformer losses are outside the automatic total unless explicitly modelled. Component sharing is ideal. Review assumptions and coverage after calculation.</p></div>`;}
export function lossFlow(row,project){if(!row?.valid)return '<p>No complete power balance is available for this operating point.</p>';const input=row.outputPower+row.totalLoss,denom=input||1;let offset=0;const parts=[{name:'Delivered output',value:row.outputPower,color:'#c6f278'},...CATEGORIES.map((k,j)=>({name:LABELS[k],value:row.categories[k],color:palette[(j+1)%palette.length]})).filter(p=>p.value>0)];let svg=`<svg class="chart" viewBox="0 0 720 105" role="img" aria-label="Power flow: calculated input splits into delivered output and included losses"><text x="10" y="20">Calculated input: ${n(input)} W</text>`;for(const p of parts){const width=690*p.value/denom;svg+=`<rect x="${10+offset}" y="35" width="${width}" height="35" fill="${p.color}"><title>${e(p.name)}: ${n(p.value)} W</title></rect>`;offset+=width;}svg+='</svg>';let measured=null;try{const w=project.waveforms.find(w=>w.id===row.waveformId);if(project.operating.inputPairs?.some(p=>p.v&&p.i))measured=outputPower(sliceWaveform(w,project.operating),{...project.operating,outputPairs:project.operating.inputPairs,balancedOutput:project.operating.balancedInput});}catch{}return svg+`<p>Delivered output <b>${n(row.outputPower)} W</b> + included losses <b>${n(row.totalLoss)} W</b> = calculated input <b>${n(input)} W</b>.</p><div class="flow-losses">${row.devices.map((d,j)=>`<div><b>${e(d.instanceName)}</b> ${n(d.total)} W<div class="loss-mini" style="width:${Math.max(1,100*d.total/(row.totalLoss||1))}%;background:${palette[j%palette.length]}"></div><span class="caption">${CATEGORIES.filter(k=>d.categories[k]>0).map(k=>e(LABELS[k])+': '+n(d.categories[k])+' W').join(' · ')}</span></div>`).join('')}</div>${measured!==null?`<p class="caption">Mapped waveform input: ${n(measured)} W. Difference from calculated input: ${n(measured-input)} W. This discrepancy is not allocated to a fabricated loss category.</p>`:''}`;}
export function operatingDashboard(row,project,graph,interactive=true){if(!row)return '';return `<section class="panel" id="operatingDashboard"><h2>Selected operating point</h2><p><b>Vin ${n(row.vin)} V · Vout ${n(row.vout)} V · Pout ${n(row.outputPower)} W</b> · ${e(resultState(row,project))}</p><p>Efficiency: ${n(row.efficiency)}% · included losses: ${n(row.totalLoss)} W</p><div class="grid2"><div><h3>Power flow</h3>${lossFlow(row,project)}</div><div><h3>Component temperatures</h3>${graph(row.devices.filter(d=>Number.isFinite(d.temperature)).map((d,j)=>({name:d.instanceName+' · '+(d.valid?'evaluated':'last trial'),color:palette[j%palette.length],scatter:true,points:[[j+1,d.temperature]]})),{xLabel:'Component index (legend)',yLabel:'Temperature [°C]',height:230})}${row.devices.map((d,j)=>`<p>${j+1}. ${e(d.instanceName)}: ${n(d.temperature)} °C ${d.valid?'':'(failed / last trial)'}</p>`).join('')}${interactive?'<button class="ghost" data-open-debug>Inspect selected point in debug ↗</button>':''}</div></div></section>`;}
export function coverageView(row,project,graph){if(!row)return '';return row.devices.map(device=>{const candidate=project.instances.find(i=>i.id===device.instanceId)?.candidates.find(c=>c.id===device.candidateId);if(!candidate)return '';return candidate.curves.filter(c=>c.constant===undefined).map(curve=>{const queries=(device.queries||[]).filter(q=>q.curveId===curve.id);if(!queries.length)return '';const given=queries[0].given,axis=given===curve.xName?'x':'y',refs=curve.iterations.flatMap(it=>it[axis]),low=Math.min(...refs),high=Math.max(...refs),outside=queries.filter(q=>q.input<low||q.input>high||q.diagnosticNotes?.some(n=>/extrapolat|outside|fixed at reference/i.test(n))),floored=queries.filter(q=>q.zeroFloorApplied);return `<details><summary>${e(device.instanceName+' / '+device.part)} · ${e(characteristicTitle(curve))}: ${outside.length?'reference conditions need review':'within sampled axis range'}${floored.length?' · zero flooring used':''}</summary><p class="caption">${queries.length} retained engine queries (sampled for display, not a time-weighted coverage percentage). Axis range ${n(low)}–${n(high)} ${e(given)}. ${outside.length} retained queries outside the axis or with reference-condition notes. ${floored.length} retained queries used a zero floor. Stored raw projections are plotted.</p>${graph(curve.iterations.map((it,j)=>({name:'Reference '+(j+1),points:it.x.map((x,k)=>[x,it.y[k]])})).concat([{name:'Queried values',color:'#ffb454',scatter:true,points:queries.filter(q=>Number.isFinite(q.rawOutput??q.output)).map(q=>given===curve.xName?[q.input,q.rawOutput??q.output]:[q.rawOutput??q.output,q.input])}]),{xLabel:curve.xName+' (SI)',yLabel:curve.yName+' (SI)'})}</details>`;}).join('');}).join('')||'<p>No curve-query samples are available for this point.</p>';}
export function thermalView(row,graph){return (row?.devices||[]).map(d=>{const h=d.thermalHistory||[];if(!h.length)return `<p>${e(d.instanceName)}: fixed temperature, or calculation stopped before a thermal iteration.</p>`;return `<h3>${e(d.instanceName)} · ${d.valid?'Converged':'Failed / last recorded iterations'}</h3>${graph([{name:'Trial temperature',points:h.map(v=>[v.iteration,v.temperature])},{name:'Next equilibrium target',points:h.filter(v=>Number.isFinite(v.target)).map(v=>[v.iteration,v.target])},{name:'Temperature limit',color:'#ff6b6b',points:[[1,h[0].limit],[h.at(-1).iteration,h[0].limit]]}],{xLabel:'Iteration',yLabel:'Temperature [°C]'})}<p class="caption">Last residual: ${n(h.at(-1).residual)} °C. Independent steady-state thermal model; shared heatsink coupling is not represented.</p>`;}).join('');}
export function alternativeView(results,waveformId,graph){const rows=results.rows.filter(r=>r.waveformId===waveformId);return `<p class="caption">Same selected operating point across alternatives. Colours consistently identify combination numbers. Failed/incomplete values are omitted, never replaced with zero.</p><div class="grid2"><div>${graph(results.ranking.flatMap((rank,j)=>{const valid=results.rows.filter(r=>r.combination===rank.combination&&r.valid),slices=[...new Set(valid.map(r=>r.vin+' / '+r.vout))];return slices.map(slice=>({name:'Combination '+rank.combination+' · '+slice+' V',color:palette[j%palette.length],points:valid.filter(r=>r.vin+' / '+r.vout===slice).sort((a,b)=>a.outputPower-b.outputPower).map(r=>[r.outputPower,r.efficiency])}));}),{xLabel:'Output power [W] (separate voltage slices)',yLabel:'Efficiency [%]'})}</div><div>${rows.map((r,j)=>`<h3 style="color:${palette[j%palette.length]}">Combination ${r.combination}</h3><p>${r.valid?n(r.totalLoss)+' W · '+n(r.efficiency)+'%':'Incomplete / failed'}</p>${r.valid?`<div class="stacked-loss" style="width:${100*r.totalLoss/Math.max(...rows.filter(v=>v.valid).map(v=>v.totalLoss),1)}%">${CATEGORIES.filter(k=>r.categories[k]>0).map((k,index)=>`<span style="width:${100*r.categories[k]/r.totalLoss}%;background:${palette[j%palette.length]};opacity:${.35+.65*index/Math.max(1,CATEGORIES.length-1)}" title="${e(LABELS[k])}: ${n(r.categories[k])} W"></span>`).join('')}</div>`:''}${r.valid?CATEGORIES.filter(k=>r.categories[k]>0).map(k=>`<div>${e(LABELS[k])}: ${n(r.categories[k])} W<div class="loss-mini" style="width:${100*r.categories[k]/Math.max(...rows.filter(v=>v.valid).map(v=>v.totalLoss),1)}%;background:${palette[j%palette.length]}"></div></div>`).join(''):''}<p class="caption">${r.devices.map(d=>e(d.instanceName)+': '+n(d.temperature)+' °C'+(d.valid?'':' (last trial)')).join(' · ')}</p>`).join('')}</div></div>`;}
